type AlefHandle = u64;
const HANDLE_INDEX_MASK: u64 = u32::MAX as u64;

#[derive(Debug)]
enum HandleError {
    InvalidZero,
    UnknownSlot,
    StaleGeneration,
    WrongType,
    RegistryPoisoned,
    HandleBusy,
    AliasedHandle,
}

impl std::fmt::Display for HandleError {
    fn fmt(&self, formatter: &mut std::fmt::Formatter<'_>) -> std::fmt::Result {
        let message = match self {
            Self::InvalidZero => "zero is not a valid handle",
            Self::UnknownSlot => "handle refers to an unknown slot",
            Self::StaleGeneration => "handle generation is stale",
            Self::WrongType => "handle has the wrong type",
            Self::RegistryPoisoned => "handle registry lock is poisoned",
            Self::HandleBusy => "handle is currently in use",
            Self::AliasedHandle => "the same handle was passed more than once",
        };
        formatter.write_str(message)
    }
}

type ErasedHandleValue = std::sync::Arc<std::sync::Mutex<Box<dyn std::any::Any + Send>>>;

struct HandleSlot {
    generation: u32,
    type_id: std::any::TypeId,
    value: Option<ErasedHandleValue>,
}

#[derive(Default)]
struct HandleRegistry {
    slots: Vec<HandleSlot>,
}

impl HandleRegistry {
    fn insert<T: std::any::Any + Send>(&mut self, value: T) -> AlefHandle {
        let entry = std::sync::Arc::new(std::sync::Mutex::new(Box::new(value) as Box<dyn std::any::Any + Send>));
        let type_id = std::any::TypeId::of::<T>();
        if let Some((index, slot)) = self.slots.iter_mut().enumerate().find(|(_, slot)| slot.value.is_none()) {
            slot.type_id = type_id;
            slot.value = Some(entry);
            return encode_handle(index, slot.generation);
        }
        self.slots.push(HandleSlot {
            generation: 1,
            type_id,
            value: Some(entry),
        });
        encode_handle(self.slots.len() - 1, 1)
    }

    fn get(&self, handle: AlefHandle) -> Result<ErasedHandleValue, HandleError> {
        let (index, generation) = decode_handle(handle)?;
        let slot = self.slots.get(index).ok_or(HandleError::UnknownSlot)?;
        if slot.generation != generation {
            return Err(HandleError::StaleGeneration);
        }
        slot.value.clone().ok_or(HandleError::StaleGeneration)
    }

    fn get_typed(&self, handle: AlefHandle, expected_type: std::any::TypeId) -> Result<ErasedHandleValue, HandleError> {
        let (index, generation) = decode_handle(handle)?;
        let slot = self.slots.get(index).ok_or(HandleError::UnknownSlot)?;
        if slot.generation != generation {
            return Err(HandleError::StaleGeneration);
        }
        let value = slot.value.as_ref().ok_or(HandleError::StaleGeneration)?;
        if slot.type_id != expected_type {
            return Err(HandleError::WrongType);
        }
        Ok(value.clone())
    }

    fn detach<T: std::any::Any + Send>(&mut self, handle: AlefHandle) -> Result<ErasedHandleValue, HandleError> {
        let (index, generation) = decode_handle(handle)?;
        let slot = self.slots.get_mut(index).ok_or(HandleError::UnknownSlot)?;
        if slot.generation != generation {
            return Err(HandleError::StaleGeneration);
        }
        if slot.value.is_none() {
            return Err(HandleError::StaleGeneration);
        }
        if slot.type_id != std::any::TypeId::of::<T>() {
            return Err(HandleError::WrongType);
        }
        let value = slot.value.take().ok_or(HandleError::StaleGeneration)?;
        slot.generation = next_generation(slot.generation);
        Ok(value)
    }

    fn take<T: std::any::Any + Send>(&mut self, handle: AlefHandle) -> Result<T, HandleError> {
        let (index, generation) = decode_handle(handle)?;
        let slot = self.slots.get_mut(index).ok_or(HandleError::UnknownSlot)?;
        if slot.generation != generation {
            return Err(HandleError::StaleGeneration);
        }
        if slot.value.is_none() {
            return Err(HandleError::StaleGeneration);
        }
        if slot.type_id != std::any::TypeId::of::<T>() {
            return Err(HandleError::WrongType);
        }
        let value = slot.value.take().ok_or(HandleError::StaleGeneration)?;
        let mutex = std::sync::Arc::try_unwrap(value).map_err(|value| {
            slot.value = Some(value);
            HandleError::HandleBusy
        })?;
        slot.generation = next_generation(slot.generation);
        let boxed = mutex.into_inner().map_err(|_| HandleError::RegistryPoisoned)?;
        boxed
            .downcast::<T>()
            .map(|value| *value)
            .map_err(|_| HandleError::WrongType)
    }
}

