fn handle_registry() -> &'static std::sync::Mutex<HandleRegistry> {
    HANDLE_REGISTRY.get_or_init(|| std::sync::Mutex::new(HandleRegistry::default()))
}

fn insert_handle<T: std::any::Any + Send>(value: T) -> Result<AlefHandle, HandleError> {
    let mut registry = handle_registry().lock().map_err(|_| HandleError::RegistryPoisoned)?;
    Ok(registry.insert(value))
}

struct SerializedHandle<T: 'static> {
    json: String,
    marker: std::marker::PhantomData<fn() -> T>,
}

fn insert_serialized_handle<T: serde::Serialize + 'static>(value: &T) -> Result<AlefHandle, String> {
    let json = serde_json::to_string(value).map_err(|error| error.to_string())?;
    insert_handle(SerializedHandle::<T> {
        json,
        marker: std::marker::PhantomData,
    })
    .map_err(|error| error.to_string())
}

fn with_handle<T: std::any::Any + Send, R>(
    handle: AlefHandle,
    operation: impl FnOnce(&T) -> R,
) -> Result<R, HandleError> {
    let value = {
        let registry = handle_registry().lock().map_err(|_| HandleError::RegistryPoisoned)?;
        registry.get(handle)?
    };
    let guard = value.lock().map_err(|_| HandleError::RegistryPoisoned)?;
    let typed = guard.downcast_ref::<T>().ok_or(HandleError::WrongType)?;
    Ok(operation(typed))
}

struct HandleRequest {
    handle: AlefHandle,
    expected_type: std::any::TypeId,
}

fn acquire_handles(requests: &[HandleRequest]) -> Result<Vec<(AlefHandle, ErasedHandleValue)>, HandleError> {
    let mut ordered = requests.iter().collect::<Vec<_>>();
    ordered.sort_by_key(|request| request.handle);
    if ordered.windows(2).any(|pair| pair[0].handle == pair[1].handle) {
        return Err(HandleError::AliasedHandle);
    }
    let registry = handle_registry().lock().map_err(|_| HandleError::RegistryPoisoned)?;
    let mut values = Vec::with_capacity(ordered.len());
    for request in ordered {
        values.push((
            request.handle,
            registry.get_typed(request.handle, request.expected_type)?,
        ));
    }
    Ok(values)
}

fn locked_handle_ptr<T: std::any::Any + Send>(
    guards: &mut [(AlefHandle, std::sync::MutexGuard<'_, Box<dyn std::any::Any + Send>>)],
    handle: AlefHandle,
) -> Result<*mut T, HandleError> {
    let (_, guard) = guards
        .iter_mut()
        .find(|(candidate, _)| *candidate == handle)
        .ok_or(HandleError::UnknownSlot)?;
    guard
        .downcast_mut::<T>()
        .map(|value| value as *mut T)
        .ok_or(HandleError::WrongType)
}

fn with_handle_mut<T: std::any::Any + Send, R>(
    handle: AlefHandle,
    operation: impl FnOnce(&mut T) -> R,
) -> Result<R, HandleError> {
    let value = {
        let registry = handle_registry().lock().map_err(|_| HandleError::RegistryPoisoned)?;
        registry.get(handle)?
    };
    let mut guard = value.lock().map_err(|_| HandleError::RegistryPoisoned)?;
    let typed = guard.downcast_mut::<T>().ok_or(HandleError::WrongType)?;
    Ok(operation(typed))
}

// Freeing is deferred destruction: the slot is detached at once, so every later use of the
// handle fails as stale, but the object is dropped by whoever releases the last `Arc`. A call that
// is still running holds one, so `T::drop` runs when that call returns (on its thread), never
// under it. The drop happens outside the registry lock so a `Drop` impl cannot deadlock on it.
fn remove_handle<T: std::any::Any + Send>(handle: AlefHandle) -> Result<(), HandleError> {
    let detached = {
        let mut registry = handle_registry().lock().map_err(|_| HandleError::RegistryPoisoned)?;
        registry.detach::<T>(handle)?
    };
    drop(detached);
    Ok(())
}

fn take_handle<T: std::any::Any + Send>(handle: AlefHandle) -> Result<T, HandleError> {
    let mut registry = handle_registry().lock().map_err(|_| HandleError::RegistryPoisoned)?;
    registry.take::<T>(handle)
}

fn encode_handle(index: usize, generation: u32) -> AlefHandle {
    ((generation as u64) << 32) | ((index as u64) + 1)
}

fn decode_handle(handle: AlefHandle) -> Result<(usize, u32), HandleError> {
    if handle == 0 {
        return Err(HandleError::InvalidZero);
    }
    let encoded_index = handle & HANDLE_INDEX_MASK;
    if encoded_index == 0 {
        return Err(HandleError::UnknownSlot);
    }
    Ok(((encoded_index - 1) as usize, (handle >> 32) as u32))
}

fn next_generation(generation: u32) -> u32 {
    let next = generation.wrapping_add(1);
    if next == 0 { 1 } else { next }
}

