/// Return the HTTP status code for the error pointed to by `err`.
/// Returns `0` if `err` is null.
#[unsafe(no_mangle)]
pub unsafe extern "C" fn spikard_graph_ql_error_status_code(err: *const spikard_graphql::GraphQLError) -> u16 {
    if err.is_null() {
        return 0;
    }
    // SAFETY: caller guarantees `err` points to a live `spikard_graphql::GraphQLError` value
    // allocated by this library, or is null (checked above).
    unsafe { (*err).status_code() }
}

/// Return whether the error pointed to by `err` is transient.
/// Returns `false` if `err` is null.
#[unsafe(no_mangle)]
pub unsafe extern "C" fn spikard_graph_ql_error_is_transient(err: *const spikard_graphql::GraphQLError) -> bool {
    if err.is_null() {
        return false;
    }
    // SAFETY: caller guarantees `err` points to a live `spikard_graphql::GraphQLError` value
    // allocated by this library, or is null (checked above).
    unsafe { (*err).is_transient() }
}

/// Return the machine-readable error category string for the error pointed
/// to by `err` as a heap-allocated, NUL-terminated C string.
/// The caller must free the returned pointer with `spikard_graph_ql_error_error_type_free`.
/// Returns a null pointer if `err` is null.
#[unsafe(no_mangle)]
pub unsafe extern "C" fn spikard_graph_ql_error_error_type(
    err: *const spikard_graphql::GraphQLError,
) -> *mut std::ffi::c_char {
    if err.is_null() {
        return std::ptr::null_mut();
    }
    // SAFETY: caller guarantees `err` points to a live `spikard_graphql::GraphQLError` value
    // allocated by this library, or is null (checked above).
    let s = unsafe { (*err).error_type() };
    // SAFETY: `error_type()` returns a `'static str` containing no NUL bytes.
    std::ffi::CString::new(s)
        .map(|c| c.into_raw())
        .unwrap_or(std::ptr::null_mut())
}

/// Free a string previously returned by `spikard_graph_ql_error_error_type`.
/// Passing a null pointer is a no-op.
#[unsafe(no_mangle)]
pub unsafe extern "C" fn spikard_graph_ql_error_error_type_free(ptr: *mut std::ffi::c_char) {
    if !ptr.is_null() {
        // SAFETY: `ptr` was allocated by `CString::into_raw` inside
        // `spikard_graph_ql_error_error_type` and is now being reclaimed by the matching
        // `CString::from_raw`.  Passing null is explicitly allowed.
        unsafe { drop(std::ffi::CString::from_raw(ptr)) };
    }
}
